// CSD_RATIONALE_BEGIN
// Root cause of mode_A failures (144/300): previous strategies
// (ConstrainedGeneration in attempt 71, RegenerateUnitOnGroundingFailure in
// attempts 66-70) terminate constrained generation at the FIRST complete SQL
// parse. Evidence: avg 8.68 generated tokens (median 7), only 7.7 constrained
// steps/example. Correct Spider SQL typically requires 15–80 tokens including
// WHERE/JOIN/GROUP BY/ORDER BY clauses.
//
// Concrete evidence from rollouts:
//   Output:  "SELECT id FROM highschooler"            (6 tokens — valid SQL stop)
//   Correct: "SELECT id FROM highschooler WHERE name = 'Kyle'"
// The constrained generator sees "SELECT col FROM table" as IsCompletePrefix and
// stops immediately, yielding syntactically valid but semantically incomplete SQL.
//
// Fix: Replace Phases 3+4 with a single CloseSpanWithinBudget(400) call.
// Unlike ConstrainedGeneration (stops at first complete) or
// RegenerateUnitOnGroundingFailure (same termination), CloseSpanWithinBudget:
//   (1) Generates tokens forward with dead-end avoidance and parser control
//   (2) Tracks the LONGEST complete prefix seen during generation
//   (3) Closes the span at that longest complete prefix (not the first)
// With budget=400 the LM can generate full WHERE/JOIN/ORDER BY clauses before
// the helper determines the best (longest complete) closing point.
//
// Budget ceiling: Phase1(5) + Phase2(1) + Phase3+4(400) = 406 << 900.
// Expected avg runtime: ~25–50 constrained tokens × 0.07 s = 1.7–3.5 s/example.
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 (parser_validity):
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
// Phase 1 preamble: Loop guard includes !insideConstrainedOut, so the
//   implication is vacuous on every iteration. The only true-flip is via
//   RenderedEndsWith("<<"), at which point we set currentConstrainedOut := []
//   and IsValidPrefix([]) holds by the method precondition. EOS break leaves
//   insideConstrainedOut unchanged (still false, vacuous).
//
// Phase 2 OpenConstrainedSpan: Runs only when !insideConstrainedOut.
//   Postcondition sets currentConstrainedOut := []; IsValidPrefix([]) holds
//   by the method precondition. Sets insideConstrainedOut := true.
//
// Phase 3+4 CloseSpanWithinBudget: Postcondition directly guarantees
//   (!insideConstrainedOut ==> currentConstrainedOut == []) and
//   (insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)).
//   Both branches are covered by the helper's postcondition.
//
// Invariant 2 (progress): |generated| <= |generatedPrefix| + steps
//
// Phase 1: UnconstrainedStep costs 1 step and appends at most 1 token (0 on
//   EOS path via break, 1 on non-EOS path). Each iteration: steps += 1,
//   |generated| grows by <= 1. Invariant preserved each iteration.
//
// Phase 2: OpenConstrainedSpan costs 1 step and appends exactly 1 "<<" token.
//   steps += 1, |generated| += 1. Invariant preserved (1:1 ratio).
//
// Phase 3+4: CloseSpanWithinBudget postcondition: |generatedOut| <= |generated|
//   + closeBudget. We assign steps += closeBudget. So
//   |generatedOut| <= |generatedPrefix| + steps_before_phase34 + closeBudget
//               = |generatedPrefix| + new_steps. Invariant preserved.
//   Generated tokens consumed by dead-end avoidance or EOS that are not
//   appended visibly still count against closeBudget, so visible growth is
//   bounded by closeBudget as required.
//
// Precondition for CloseSpanWithinBudget (|currentConstrainedOut| <= |generated|):
//   After Phase 2: currentConstrainedOut := [], |generated| >= 1. Holds trivially.
//   If Phase 2 skipped (insideConstrained true on entry): method precondition
//   guarantees |currentConstrained| <= |generatedPrefix| = |generated|. Holds.
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm, "Output SQL: <<query>> where query is a valid SQL SELECT statement using ONLY the exact table and column names from the provided schema. The SQL must be placed between << and >>. No explanation, no markdown, no aliases not in the schema.");

var steps: nat := 0;

// Phase 1: Short preamble (at most 5 steps) to let model emit "SQL: <<" naturally
while steps < maxSteps && steps < 5 && !insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  var next := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  if next == eosToken {
    break;
  } else {
    generated := generated + [next];
    if RenderedEndsWith(generated, "<<") {
      insideConstrainedOut := true;
      currentConstrainedOut := [];
    }
  }
}

// Phase 2: Force "<<" if not already inside constrained span
if !insideConstrainedOut && steps < maxSteps {
  var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
  generated := og;
  insideConstrainedOut := oi;
  currentConstrainedOut := oc;
  steps := steps + 1;
}

// Phase 3+4 combined: Generate full SQL and close span using CloseSpanWithinBudget.
// Budget=400 gives the LM room to generate WHERE/JOIN/GROUP BY/ORDER BY clauses.
// CloseSpanWithinBudget tracks the LONGEST complete prefix seen (not the first),
// preventing the premature-termination failure that produced truncated SQL in
// attempts 66–71 (ConstrainedGeneration and RegenerateUnitOnGroundingFailure
// both stop at the first complete parse, yielding "SELECT col FROM table"
// without WHERE clauses that correct answers require).
if insideConstrainedOut && steps < maxSteps {
  var remaining := maxSteps - steps;
  var closeBudget: nat;
  if remaining <= 400 {
    closeBudget := remaining;
  } else {
    closeBudget := 400;
  }
  var cg, ci, cc := helpers.CloseSpanWithinBudget(
    lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
  );
  generated := cg;
  insideConstrainedOut := ci;
  currentConstrainedOut := cc;
  steps := steps + closeBudget;
}

cost := steps;

